WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_age_b_relation_now'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '已知关系求现年龄', 'kp-age-b-relation-now', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "已知关系求现年龄"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心推论：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "把抽象倍数具象化，用比例份数设未知数。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“甲今年的年龄是乙的 3 倍，5 年后是乙的 2 倍。求甲今年多少岁？”。不给具体数字，只给两套条件。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[找到当前时间点的倍数关系] --> B[设份数: 如甲是乙3倍, 设乙=x, 甲=3x]\nB --> C[利用另一个时间点(如5年后)的条件建立等式]\nC --> D[5年后甲=3x+5, 乙=x+5]\nD --> E[列出第二套倍数关系: 3x+5 = 2*(x+5)]\nE --> F[解出 x, 反推出现龄]"}}]}$$ AS jsonb), NULL, '已知关系求现年龄的核心考点与实战推导。', category_node.id, CAST('["数量关系", "年龄问题", "已知关系求现年龄"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_age_b_relation_now", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
